{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Security group and rules lack descriptions",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The security group and its inline rules have no descriptions, reducing auditability and making it difficult to determine their intended purpose."
    },
    {
      "check_id": "CKV_AWS_277",
      "title": "Unrestricted inbound traffic on all ports and protocols",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The ingress rule permits every protocol and port from 0.0.0.0/0, exposing any resource associated with this security group to arbitrary internet traffic."
    },
    {
      "check_id": "CKV_AWS_24",
      "title": "SSH is exposed to the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Because all protocols and ports are allowed from 0.0.0.0/0, the rule also exposes TCP port 22 to internet-based scanning and attacks."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "RDP is exposed to the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "Because all protocols and ports are allowed from 0.0.0.0/0, the rule also exposes TCP port 3389 to internet-based scanning and attacks."
    },
    {
      "check_id": "CKV_AWS_260",
      "title": "Unencrypted HTTP is exposed to the internet",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The unrestricted ingress rule includes port 80 from 0.0.0.0/0, allowing public unencrypted HTTP access without any demonstrated requirement in this file."
    },
    {
      "check_id": "CKV_AWS_382",
      "title": "Unrestricted outbound traffic",
      "resource": "aws_security_group.lb",
      "severity": "MEDIUM",
      "explanation": "The egress rule permits traffic to any IPv4 destination over every port and protocol, enabling unrestricted outbound connectivity if the group is attached."
    }
  ],
  "patched_code": "resource \"aws_security_group\" \"lb\" {\n  name        = \"allow-all-lb\"\n  description = \"Security group for the load balancer\"\n  vpc_id      = data.aws_vpc.main.id\n}\n",
  "fix_summary": "Added a security group description and removed the unrestricted ingress and egress rules. The security group now denies traffic by default until explicitly scoped rules are defined."
}
